From 5dead65b720d8a9bc2aefc0e918cdb7621dc1ec5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 20:15:47 +0100
Subject: [PATCH] klipper: don't keep history of what is copied in a private
 activity

Activities can be set to not track usage, but everything copied in one
still ended up in the clipboard history, which is also saved on disk.
Now it is kept out of the history and treated as sensitive data instead.

BUG: 391046
---
 klipper/CMakeLists.txt   |  1 +
 klipper/historymodel.cpp | 17 ++++++++++++++++-
 klipper/historymodel.h   |  7 +++++++
 3 files changed, 24 insertions(+), 1 deletion(-)

diff --git a/klipper/CMakeLists.txt b/klipper/CMakeLists.txt
index da747f5a71..fc1af1e26c 100644
--- a/klipper/CMakeLists.txt
+++ b/klipper/CMakeLists.txt
@@ -53,6 +53,7 @@ target_link_libraries(klipper
     KF6::WindowSystem
     KF6::XmlGui
     Plasma::PlasmaQuick
+    Plasma::Activities
     Wayland::Client
     LayerShellQt::Interface
     ZLIB::ZLIB
diff --git a/klipper/historymodel.cpp b/klipper/historymodel.cpp
index 8112dadb5b..51ef682018 100644
--- a/klipper/historymodel.cpp
+++ b/klipper/historymodel.cpp
@@ -28,6 +28,8 @@
 #include <KLocalizedString>
 #include <KMessageBox>
 #include <KMessageDialog>
+#include <KSharedConfig>
+#include <PlasmaActivities/Consumer>

 #include "config-klipper.h"
 #include "historyitem.h"
@@ -199,6 +201,7 @@ std::shared_ptr<HistoryModel> HistoryModel::self()
 HistoryModel::HistoryModel()
     : QAbstractListModel(nullptr)
     , m_clip(SystemClipboard::self())
+    , m_activityConsumer(new KActivities::Consumer(this))
 {
     if (!QSqlDatabase::isDriverAvailable(u"QSQLITE"_s)) {
         qCCritical(KLIPPER_LOG) << "SQLITE driver isn't available";
@@ -1049,7 +1052,7 @@ void HistoryModel::checkClipData(QClipboard::Mode mode, const QMimeData *data)
     // this must be below the "bNoNullClipboard" handling code!
     // XXX: I want a better handling of selection/clipboard in general.
     // XXX: Order sensitive code. Must die.
-    const bool isPassword = data->data(QStringLiteral("x-kde-passwordManagerHint")) == QByteArrayView("secret");
+    const bool isPassword = data->data(QStringLiteral("x-kde-passwordManagerHint")) == QByteArrayView("secret") || isInPrivateActivity();
     const bool selectionMode = mode == QClipboard::Selection;
     if (isPassword) {
         // A password stays out of the history, but keeping the buffers the same is still the user's choice.
@@ -1138,6 +1141,18 @@ void HistoryModel::setHasPassword(QClipboard::Mode mode, bool hasPassword)
     Q_EMIT hasPasswordChanged();
 }

+bool HistoryModel::isInPrivateActivity() const
+{
+    const QString activity = m_activityConsumer->currentActivity();
+    if (activity.isEmpty()) {
+        return false;
+    }
+    // The activity manager doesn't announce changes to this list, so read it fresh
+    const KSharedConfig::Ptr config = KSharedConfig::openConfig(u"kactivitymanagerd-pluginsrc"_s, KConfig::NoGlobals);
+    config->reparseConfiguration();
+    return config->group(u"Plugin-org.kde.ActivityManager.Resources.Scoring"_s).readEntry("off-the-record-activities", QStringList()).contains(activity);
+}
+
 void HistoryModel::setURLGrabber(URLGrabber *grabber)
 {
     m_urlGrabber = grabber;
